CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE FUNCTION public.assign_verified_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF lower(NEW.email)='agastyapurohit03@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER assign_verified_admin AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_verified_admin();
CREATE TABLE public.enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), name text NOT NULL CHECK(char_length(name) BETWEEN 2 AND 80), phone text NOT NULL CHECK(char_length(phone) BETWEEN 10 AND 15), email text NOT NULL CHECK(char_length(email)<=120), category text NOT NULL CHECK(category IN ('Residential','Commercial','Plots & Land')), budget text NOT NULL CHECK(budget IN ('Under ₹50 L','₹50 L – 1 Cr','₹1 – 3 Cr','₹3 – 5 Cr','Above ₹5 Cr')), city text NOT NULL DEFAULT '' CHECK(char_length(city)<=60), context text NOT NULL CHECK(char_length(context) BETWEEN 1 AND 200));
GRANT SELECT ON public.enquiries TO authenticated;
GRANT ALL ON public.enquiries TO service_role;
ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read enquiries" ON public.enquiries FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), slug text UNIQUE NOT NULL CHECK(char_length(slug) BETWEEN 1 AND 100), title text NOT NULL CHECK(char_length(title) BETWEEN 2 AND 120), category text NOT NULL CHECK(category IN ('Residential','Commercial','Plots & Land')), type text NOT NULL CHECK(type IN ('New Projects','Resale')), property_type text NOT NULL CHECK(char_length(property_type) BETWEEN 1 AND 80), location text NOT NULL CHECK(char_length(location) BETWEEN 2 AND 160), price text NOT NULL CHECK(char_length(price) BETWEEN 1 AND 80), beds integer CHECK(beds BETWEEN 0 AND 30), area text NOT NULL CHECK(char_length(area) BETWEEN 1 AND 80), image text NOT NULL CHECK(char_length(image) BETWEEN 1 AND 2048), config text NOT NULL DEFAULT '' CHECK(char_length(config)<=160), status text NOT NULL DEFAULT '' CHECK(char_length(status)<=80), summary text NOT NULL DEFAULT '' CHECK(char_length(summary)<=3000), highlights text[] NOT NULL DEFAULT '{}', featured boolean NOT NULL DEFAULT false, brochure_url text NOT NULL DEFAULT '' CHECK(char_length(brochure_url)<=2048));
GRANT SELECT ON public.properties TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.properties TO authenticated;
GRANT ALL ON public.properties TO service_role;
ALTER TABLE public.properties ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public property catalogue" ON public.properties FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admins add properties" ON public.properties FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins update properties" ON public.properties FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins remove properties" ON public.properties FOR DELETE TO authenticated USING(public.has_role(auth.uid(),'admin'));